import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"宿主服务","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/sdk/services.md","filePath":"zh-CN/dev-guide/sdk/services.md","lastUpdated":1783414071000}'),c={name:"zh-CN/dev-guide/sdk/services.md"};function a(i,e,s,n,l,u){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="宿主服务" tabindex="-1">宿主服务 <a class="header-anchor" href="#宿主服务" aria-label="Permalink to &quot;宿主服务&quot;">​</a></h1><p><code>PluginSdk.Services</code> 里的静态服务，把宿主应用的功能暴露给插件——每一个都是包装了宿主启动时接好 的委托的薄静态类，所以不管底层实际运行的是什么，插件的调用方式都一样。</p><table tabindex="0"><thead><tr><th>服务</th><th>用途</th></tr></thead><tbody><tr><td><code>TranslationService</code></td><td><code>Get(key)</code> / <code>Format(key, args)</code> 在运行时按当前语言查询;<code>LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> 加载插件自己内嵌的 JSON 语言包;<code>GetSupportedCultures(assembly)</code>。</td></tr><tr><td><code>IconService</code></td><td><code>GetIcon(path, isDir)</code> 和 <code>GetThumbnail(path, size)</code> —— 带缓存的 Shell 图标/缩略图提取，插件不需要自己调 Windows 图标 API。</td></tr><tr><td><code>FavoritesService</code></td><td><code>GetFavorites()</code> —— 只读访问用户的<a href="./../../user-guide/settings/favorites.html">收藏夹</a>列表(<code>FavoriteItem</code>:Name、Path)。</td></tr><tr><td><code>HistoryService</code></td><td><code>GetHistoryPaths()</code> —— 来自<a href="./../../user-guide/settings/history.html">历史记录</a>的最近访问路径。</td></tr><tr><td><code>FileMetadataService</code></td><td><code>GetMetadataAsync(paths)</code> —— 批量查询 Size/Created/Modified/Accessed(<code>FileMetadata</code> record struct)，适合插件添加一个需要对大量结果同时取这些数据的<a href="./ui-extensions.html#iresultcolumnprovider">结果列</a>。</td></tr><tr><td><code>DirectoryIndexerService</code></td><td><code>RegisterDirectory(pluginId, path, recursive, filterPattern)</code> / <code>UnregisterDirectories(pluginId)</code> / <code>SearchDirectoriesAsync(pluginId, query, token)</code> / <code>NotifyDirectoryChanged(pluginId)</code> —— 让插件注册自己的目录进行后台索引和 USN 监听，而不用自己重新实现这套机制。</td></tr><tr><td><code>PluginSettingsService</code></td><td><code>GetSetting&lt;T&gt;(pluginId, key, defaultValue)</code> —— 从宿主的配置存储里只读访问插件自己持久化的设置。</td></tr><tr><td><code>Logger</code></td><td><code>Log(message, level = LogLevel.Info)</code> —— 写入 App 的日志文件，和宿主自己的日志行一样，显示在<strong>设置 → 运行状态 → App</strong> 里。</td></tr></tbody></table><p><code>LogLevel</code> 是 <code>Error</code> / <code>Warn</code> / <code>Info</code> / <code>Debug</code>，与 <a href="./../../user-guide/settings/service-status.html">运行状态日志查看器</a>里的等级过滤器一致。</p>',4)])])}const p=t(c,[["render",a]]);export{g as __pageData,p as default};
